        uint256 beforeValue = cakeDividendTracker.totalDividendsDistributed();
        cakeDividendTracker.distributeDividends(1_000_000 * 1e18);
        uint256 afterValue = cakeDividendTracker.totalDividendsDistributed();
        assertGt(afterValue, beforeValue, "totalDividendsDistributed did not increase");
